// fast atan2 (max err ~1e-3 rad) — a real atan2 per pixel is the whole frame budget
function fatan2(y, x) {
  const ax = x < 0 ? -x : x, ay = y < 0 ? -y : y;
  const mx = ax > ay ? ax : ay, mn = ax > ay ? ay : ax;
  const a = mn / (mx + 1e-12), s = a * a;
